9	@PublicApi
10	public class TreeTransformerUtil {
11	
12	    public static <T> TraversalControl changeNode(TraverserContext<T> context, T changedNode) {
13	        NodeZipper<T> zipperWithChangedNode = context.getVar(NodeZipper.class).withNewNode(changedNode);
14	        NodeMultiZipper<T> multiZipper = context.getCurrentAccumulate();
15	        context.setAccumulate(multiZipper.withNewZipper(zipperWithChangedNode));
16	        context.changeNode(changedNode);
17	        return TraversalControl.CONTINUE;
18	    }
19	
20	    public static <T> TraversalControl deleteNode(TraverserContext<T> context) {
21	        NodeZipper<T> curZipper = context.getVar(NodeZipper.class);
22	        NodeAdapter<T> nodeAdaper = context.getVar(NodeAdapter.class);
23	        NodeLocation nodeLocation = curZipper.getBreadcrumbs().get(0).getLocation();
24	
25	        changeParentNode(context, parentNode -> nodeAdaper.removeChild(parentNode, nodeLocation));
26	
27	        context.deleteNode();
28	        return TraversalControl.CONTINUE;
29	    }
30	
31	    public static <T> TraversalControl changeParentNode(TraverserContext<T> context, Function<T, T> changeNodeFunction) {
32	        assertTrue(context.getParentNode() != null, "can't delete root node");
33	        NodeMultiZipper<T> multiZipper = context.getCurrentAccumulate();
34	        NodeZipper<T> curZipper = context.getVar(NodeZipper.class);
35	        NodeZipper<T> zipperForParent = multiZipper.getZipperForNode(curZipper.getParent());
36	
37	        boolean zipperForParentAlreadyExisted = true;
38	        if (zipperForParent == null) {
39	            zipperForParent = curZipper.moveUp();
40	            zipperForParentAlreadyExisted = false;
41	        }
42	        T parentNode = zipperForParent.getCurNode();
43	
44	        T newParent = changeNodeFunction.apply(parentNode);
45	
46	        NodeZipper newZipperForParent = zipperForParent.withNewNode(newParent);
47	
48	        NodeMultiZipper<T> newMultiZipper;
49	        if (zipperForParentAlreadyExisted) {
50	            newMultiZipper = multiZipper.withReplacedZipper(zipperForParent, newZipperForParent);
51	        } else {
52	            newMultiZipper = multiZipper.withNewZipper(newZipperForParent);
53	        }
54	        context.getParentContext().changeNode(newParent);
55	        context.setAccumulate(newMultiZipper);
56	        return TraversalControl.CONTINUE;
57	
58	    }
59	}
